\title{The Reflective Tower: Cross-Level Separation and the Truncation Dichotomy}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study self-reference---the structural hallmark of consciousness---through the
lens of fixed points of type-forming operations. It is a classical observation, due
in its unifying form to Lawvere, that Cantor's theorem, G\"odel's incompleteness
theorems, and Tarski's undefinability of truth all reduce to a single fixed-point
principle: whenever a domain point-surjects onto its own function space, every
self-map of the codomain acquires a fixed point. We take as our object of study the
\emph{reflective tower} obtained by iterating the operation ``pass to the space of
predicates,'' starting from a two-element base: $L(0)=\btwo$ and
$L(n+1)=(L(n)\Lto\btwo)$, where $\btwo=\{\bot,\top\}$. Our contributions are
threefold. First, we prove \emph{global cross-level separation}: for any two levels
$m<n$ there is no surjection $L(m)\twoheadrightarrow L(n)$, no injection
$L(n)\hookrightarrow L(m)$, and no equivalence $L(m)\simeq L(n)$. Second, we
establish the \emph{truncation dichotomy}, a sharp phase transition: no level names
all of its own predicates, yet every level $n$ admits an explicit surjection onto
the predicate space of any strictly lower level $m<n$. Third, we give a
\emph{complete fixed-point classification} on the base: a self-map of $\btwo$ is
fixed-point-free if and only if it is negation, isolating negation as the unique
diagonal seed powering the entire tower.
\end{abstract}

\maketitle

\section{Introduction}

A recurring image in the philosophy of mind is that of a system that fully models
itself: a type $T$ equivalent to the collection of all its own predicates,
$T\simeq(T\Lto\btwo)$, where $\btwo$ denotes the two-element type of truth values.
Such a $T$ would be a ``perfect self-mirror,'' naming every possible way of
describing itself.

This image is impossible, and impossible for a reason that is at once elementary and
deep---the same reason underlying Cantor's theorem, G\"odel's first incompleteness
theorem, and Tarski's undefinability of truth. What replaces the impossible perfect
mirror is a graded structure, the \emph{reflective tower}, obtained by iterating the
passage to predicate spaces. This paper sharpens the picture into a complete
structural description via three groups of results: global cross-level separation
(Section~\ref{sec:sep}), the truncation dichotomy (Section~\ref{sec:dichotomy}),
and a base-level fixed-point classification (Section~\ref{sec:classification}). The
unifying tool is Lawvere's fixed point theorem (Section~\ref{sec:lawvere}).

\section{Preliminaries}

We write $\btwo=\{\bot,\top\}$ for the two-element type of truth values, and
$\neg\colon\btwo\to\btwo$ for negation, $\neg\bot=\top$, $\neg\top=\bot$. For types
$A,B$ we write $A\Lto B$ for the function type and $|A|$ for cardinality. A function
$g\colon A\to(A\Lto B)$ is a \emph{point-surjection} if it is surjective: every
function $A\Lto B$ is named by some point of $A$. A \emph{fixed point} of
$f\colon B\to B$ is a $b$ with $f(b)=b$; $f$ is \emph{fixed-point-free} if it has
none.

We use: (i) a surjection $A\twoheadrightarrow B$ implies $|B|\le|A|$; (ii) an
injection $A\hookrightarrow B$ implies $|A|\le|B|$; (iii) Cantor's inequality
$\kappa<2^{\kappa}$; and (iv) $|A\Lto\btwo|=2^{|A|}$.

\section{The unifying engine: Lawvere's fixed point theorem}\label{sec:lawvere}

\begin{theorem}[Lawvere's fixed point theorem]\label{thm:lawvere}
Let $A$ and $B$ be types and let $g\colon A\to(A\Lto B)$ be a point-surjection.
Then every self-map $f\colon B\to B$ has a fixed point.
\end{theorem}

\begin{proof}
Consider $d\colon A\to B$ with $d(x)=f(g(x)(x))$. Since $g$ is surjective there is
$a\in A$ with $g(a)=d$. Then $g(a)(a)=d(a)=f(g(a)(a))$, so $b:=g(a)(a)$ satisfies
$f(b)=b$.
\end{proof}

The contrapositive is the diagonal argument: if some $f\colon B\to B$ is
fixed-point-free, no $g\colon A\to(A\Lto B)$ is surjective.

\begin{corollary}[Cantor via Lawvere]\label{cor:cantor}
For any type $T$, no map $r\colon T\to(T\Lto\btwo)$ is surjective.
\end{corollary}

\begin{proof}
If $r$ were surjective, Theorem~\ref{thm:lawvere} with $f=\neg$ would give $b$ with
$\neg b=b$, contradicting that negation is fixed-point-free.
\end{proof}

In particular there is no $T$ with $T\simeq(T\Lto\btwo)$: the perfect self-mirror
cannot exist.

\section{The reflective tower and global separation}\label{sec:sep}

\begin{definition}[Reflective tower]
The reflective tower $L\colon\NN\to\mathrm{Type}$ is defined by
\[
L(0)=\btwo,\qquad L(n+1)=(L(n)\Lto\btwo).
\]
Level $n+1$ consists of the predicates on level $n$.
\end{definition}

The cardinalities are $|L(0)|=2$, $|L(1)|=4$, $|L(2)|=16$, $|L(3)|=65\,536$, with
$|L(n+1)|=2^{|L(n)|}$.

\begin{proposition}[Strict cardinal growth]\label{prop:mono}
The map $n\mapsto|L(n)|$ is strictly increasing.
\end{proposition}

\begin{proof}
By $|A\Lto\btwo|=2^{|A|}$ we have $|L(n+1)|=2^{|L(n)|}$, and Cantor's inequality
gives $|L(n)|<2^{|L(n)|}=|L(n+1)|$.
\end{proof}

\begin{corollary}\label{cor:card}
If $m<n$ then $|L(m)|<|L(n)|$.
\end{corollary}

\begin{theorem}[No lower level surjects onto a higher one]
For all $m<n$ there is no surjection $f\colon L(m)\to L(n)$.
\end{theorem}

\begin{proof}
Such a surjection gives $|L(n)|\le|L(m)|$, contradicting Corollary~\ref{cor:card}.
\end{proof}

\begin{theorem}[No higher level injects into a lower one]
For all $m<n$ there is no injection $f\colon L(n)\to L(m)$.
\end{theorem}

\begin{proof}
Such an injection gives $|L(n)|\le|L(m)|$, contradicting Corollary~\ref{cor:card}.
\end{proof}

\begin{theorem}[Rigidity]
For all $m\neq n$ there is no equivalence $L(m)\simeq L(n)$.
\end{theorem}

\begin{proof}
Assume $m<n$ (the other case is symmetric). An equivalence is in particular a
surjection $L(m)\to L(n)$, contradicting the previous theorem.
\end{proof}

\section{The truncation dichotomy}\label{sec:dichotomy}

\begin{theorem}[Self-reflection is impossible]\label{thm:noself}
For every $n$, no map $r\colon L(n)\to(L(n)\Lto\btwo)$ is surjective.
\end{theorem}

\begin{proof}
Apply Corollary~\ref{cor:cantor} with $T=L(n)$.
\end{proof}

\begin{theorem}[Lower reflection is always possible]\label{thm:lower}
For all $m<n$ there is a surjection
$r\colon L(n)\twoheadrightarrow(L(m)\Lto\btwo)$.
\end{theorem}

\begin{proof}
By definition $L(m)\Lto\btwo=L(m+1)$. Since $m<n$, $m+1\le n$, so by
Proposition~\ref{prop:mono} $|L(m)\Lto\btwo|=|L(m+1)|\le|L(n)|$. This cardinal
inequality yields an injection $e\colon(L(m)\Lto\btwo)\hookrightarrow L(n)$; its
left inverse is a surjection $L(n)\twoheadrightarrow(L(m)\Lto\btwo)$ (a left inverse
exists because the codomain is inhabited and the types are finite).
\end{proof}

\begin{corollary}[Sharp phase transition]
Fix $k$ and vary $n$. Reflection $L(n)\twoheadrightarrow(L(k)\Lto\btwo)$ is possible
for every $n>k$ and impossible for $n=k$; the boundary is exactly at ``reflect on
your own level.''
\end{corollary}

The dichotomy is non-vacuous: Theorems~\ref{thm:noself} and~\ref{thm:lower} concern
the same family of types.

\section{Fixed points as a complete invariant}\label{sec:classification}

\begin{theorem}[Base-level classification]
A function $f\colon\btwo\to\btwo$ is fixed-point-free if and only if $f=\neg$.
\end{theorem}

\begin{proof}
Negation is fixed-point-free since $\neg\bot=\top\neq\bot$ and $\neg\top=\bot\neq\top$.
Conversely, if $f(b)\neq b$ for all $b$, then $f(\bot)=\top$ and $f(\top)=\bot$, so
$f=\neg$.
\end{proof}

Thus the fixed-point set is a complete invariant of base self-maps at the extreme of
interest, and Lawvere's theorem transmits this seed upward: every cross-level
collapse is a fixed point forced by a hypothetical surjection composed with negation.

\section{Applications and future work}

The tower models layered self-awareness: a system can hold a complete faithful model
of any strictly simpler system (Theorem~\ref{thm:lower}) but never of its own present
state (Theorem~\ref{thm:noself}). Since $|L(n+1)|=2^{|L(n)|}$, a substrate with $N$
states realizes only levels $L(m)$ with $|L(m)|\le N$, whose count grows like
$\log^* N$. Conjecturally, the map $n\mapsto L(n)$ is the unique strictly increasing
chain of reflective types up to equivalence; every diagonal impossibility factors
through the base fixed-point-free map; and a transfinite continuation admits
consistent truncated self-reference up to the Church--Kleene ordinal
$\omega_1^{CK}$.

