function DIAGONAL_ESCAPE(reflect):
    n <- length(reflect)          # reflect[i] is the predicate named by element i
    for a in 0..n-1:
        p[a] <- NOT reflect[a][a] # flip the a-th bit of the a-th named predicate
    return p                      # guaranteed absent from reflect

function CLASSIFY_BASE_MAP(f):
    fixed <- { b in {False,True} : f[b] = b }
    if fixed is empty:
        return 'negation (fixed-point-free)'
    else:
        return 'has fixed points: ' + fixed

